function quorum(n){return Math.floor(n/2)+1;}
function tolerated(n){return n-quorum(n);}
function survivesLargestAZLoss(placement){
  const n=placement.reduce((a,b)=>a+b,0);
  const largest=Math.max(...placement);
  const survivors=n-largest;
  return survivors>=quorum(n);
}
for(const n of [3,5,7]){
  console.log('n='+n+' quorum='+quorum(n)+' tolerated='+tolerated(n));
}
const spread=[2,2,1];
const skewed=[3,2];
console.log('placement 2-2-1 survives largest-AZ loss: '+survivesLargestAZLoss(spread));
console.log('placement 3-2 survives largest-AZ loss: '+survivesLargestAZLoss(skewed));
